const parsed = $('Parse Text').first().json;
const visual = $('Extract Visual').first().json;
const captionNode = $('Extract Caption').first().json;

const research = parsed.textContent?.agent_1_research_packet || '';
const caption =
  parsed.textContent?.agent_2_publish_ready_caption ||
  captionNode.artifacts?.caption ||
  '';
const imageUrl =
  $('Map R2 URL').item.json.r2_url || visual.artifacts?.image || '';

return {
  json: {
    status: 'OK',
    message: 'Content generated successfully',
    content: `${caption}\n\n![Generated Image](${imageUrl})`,
    artifacts: {
      research,
      caption,
      image: imageUrl,
    },
    id: parsed.id || visual.id || '',
    organization_id: parsed.organization_id || visual.organization_id || '',
    tenant_id: parsed.tenant_id || visual.tenant_id || '',
  },
};

const textContent = $('Parse Text').item.json.textContent;
const item = $('Parse Text').item.json.item;
const tenantId = $('Parse Text').item.json.tenant_id || item.owner_ref;
return { json: { payload: {
  p_organization_id: tenantId,
  p_content_item_id: item.id,
  p_expected_current_state: 'idea',
  p_next_state: 'research_ready',
  p_actor_ref: 'agent_content_creator',
  p_idempotency_key: 'trans_' + $execution.id + '_research',
  p_stage_payload: { artifacts: [{ artifact_key: 'res_' + $execution.id + '_' + item.id.replace(/-/g, '_'), artifact_type: 'viral_research_packet', content: textContent.agent_1_research_packet }] }
}}};

const item = $('Parse Text').first().json.item;
const tenantId = $('Parse Text').first().json.tenant_id || item.owner_ref;

let imageUrl =
  $input.first().json.images?.[0]?.url ||
  $input.first().json.data?.[0]?.url ||
  'https://placehold.co/1024x1024?text=Image+Generation+Failed';

return {
  json: {
    status: 'OK',
    message: 'Content generated successfully',
    artifacts: {
      research: $('Parse Text').first().json.textContent.agent_1_research_packet,
      caption: $('Parse Text').first().json.textContent.agent_2_publish_ready_caption,
      image: imageUrl,
    },
    id: item.id,
    organization_id: tenantId,
    tenant_id: tenantId,
  },
};

